// media cache keys carry the file's content hash, so a changed file at the same path (e.g. a rebuilt full.mp3) is re-downloaded, and the old copy is dropped
const mk=f=>f+"?h="+(HM[f]||"0");
const isMedia=p=>/\.(mp3|png|jpg|enc)$/i.test(p)&&!/catalog|\.json/.test(p);
const SHELL_FILES=FILES.filter(f=>!isMedia(f));const MEDIA_FILES=FILES.filter(isMedia);
self.addEventListener("install",e=>{e.waitUntil((async()=>{const c=await caches.open(SHELL);
  await Promise.all(SHELL_FILES.map(f=>fetch(f,{cache:"no-store"}).then(r=>r.ok&&c.put(f,r)).catch(()=>{})));await self.skipWaiting()})())});
self.addEventListener("activate",e=>{e.waitUntil((async()=>{for(const k of await caches.keys())if(k.startsWith("nova-")&&k!=SHELL&&k!=MEDIA)await caches.delete(k);
  // drop media that no longer exists in this version
  const m=await caches.open(MEDIA),keep=new Set(MEDIA_FILES.map(f=>new URL(mk(f),self.registration.scope).href));for(const r of await m.keys())if(!keep.has(r.url))await m.delete(r);
  await self.clients.claim()})())});
let filling=null;
async function fill(report){const m=await caches.open(MEDIA);let have=0;const todo=[];
  for(const f of MEDIA_FILES){if(await m.match(mk(f)))have++;else todo.push(f)}report(have);
  for(const f of todo){try{const r=await fetch(mk(f),{cache:"no-store"});if(r.ok){await m.put(mk(f),r);have++;if(have%10==0)report(have)}}catch(err){break}}report(have)}
self.addEventListener("message",e=>{const d=e.data||{};
  if(d.t=="skip")self.skipWaiting();
  if(d.t=="ver")e.source&&e.source.postMessage({t:"ver",v:V,media:MEDIA_FILES.length});
  if(d.t=="fill"){const send=n=>self.clients.matchAll().then(cs=>cs.forEach(c=>c.postMessage({t:"fill",have:n,total:MEDIA_FILES.length})));
    if(!filling)filling=fill(send).finally(()=>filling=null);e.waitUntil(filling)}});
async function rangeResp(resp,range){const b=await resp.blob();const m=/bytes=(\d*)-(\d*)/.exec(range)||[];let s=+m[1]||0,end=m[2]?+m[2]:b.size-1;end=Math.min(end,b.size-1);
  return new Response(b.slice(s,end+1),{status:206,headers:{"Content-Type":resp.headers.get("Content-Type")||"audio/mpeg","Content-Range":`bytes ${s}-${end}/${b.size}`,"Content-Length":String(end-s+1),"Accept-Ranges":"bytes"}})}
self.addEventListener("fetch",e=>{const req=e.request,u=new URL(req.url);if(req.method!="GET"||u.origin!=location.origin)return;
  const rel=u.pathname.slice(new URL(self.registration.scope).pathname.length);
  if(rel=="sw.js")return;
  if(isMedia(rel)){e.respondWith((async()=>{const m=await caches.open(MEDIA);const key=mk(rel);let hit=await m.match(key);
    if(!hit){try{const r=await fetch(key,{cache:"no-store"});if(r.ok){await m.put(key,r.clone());hit=r}else return r}catch(err){return Response.error()}}
    const range=req.headers.get("range");return range?rangeResp(hit.clone(),range):hit})());return}
  // network-first for html/js/css/json (fresh when online, cached when offline)
  e.respondWith((async()=>{const c=await caches.open(SHELL);const key=req.mode=="navigate"?"index.html":(rel||"index.html");
    try{const r=await fetch(req.mode=="navigate"?"index.html":req,{cache:"no-store"});if(r.ok)c.put(key,r.clone());return r}
    catch(err){return (await c.match(key,{ignoreSearch:true}))||(await c.match("index.html"))||Response.error()}})())});
